mapper.select:
SELECT w.id, w.coach_id AS coachId, c.coach_no AS coachNo, c.coach_name AS coachName, c.mobile, w.requested_amount AS requestedAmount, w.settlement_amount AS settlementAmount, w.actual_settlement_amount AS actualSettlementAmount, w.frozen_amount AS frozenAmount, w.account_name AS accountName, w.bank_name AS bankName, CONCAT('****', RIGHT(w.bank_card_no, 4)) AS bankCardNo, w.attachment_urls AS attachmentUrls, w.status, w.review_remark AS reviewRemark, DATE_FORMAT(w.reviewed_at, '%Y-%m-%d %H:%i:%s') AS reviewedAt, DATE_FORMAT(w.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM pt_coach_withdrawal w INNER JOIN pt_coach c ON c.id = w.coach_id AND c.deleted = 0
AND c.coach_name LIKE CONCAT('%', #{coachName}, '%')
AND w.status = #{status}
AND w.created_at >= #{beginTime}
AND w.created_at < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND EXISTS (SELECT 1 FROM pt_coach_store_rel r WHERE r.coach_id = w.coach_id AND r.store_id IN (${storeIds}))
ORDER BY w.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM pt_coach_withdrawal w INNER JOIN pt_coach c ON c.id = w.coach_id AND c.deleted = 0
AND c.coach_name LIKE CONCAT('%', #{coachName}, '%')
AND w.status = #{status}
AND w.created_at >= #{beginTime}
AND w.created_at < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND EXISTS (SELECT 1 FROM pt_coach_store_rel r WHERE r.coach_id = w.coach_id AND r.store_id IN (${storeIds}))
